"""Keep the homepage focused on the injection-moulding business after generation."""
from pathlib import Path
import re

root=Path(__file__).resolve().parents[1]
path=root/'templates/index.html'
home=path.read_text(encoding='utf-8')
# Preserve the detailed battery animation on its dedicated application page.
battery_page=root/'public/battery-components.html'
battery_template=root/'templates/battery-study.html'
if battery_page.exists() and battery_template.exists():
    battery_html=battery_page.read_text(encoding='utf-8')
    if 'id="battery-journey"' not in battery_html:
        battery_html=battery_html.replace('<div id="details">',battery_template.read_text(encoding='utf-8')+'<div id="details">',1)
        battery_page.write_text(battery_html,encoding='utf-8')
home=re.sub(r'<title>.*?</title>','<title>Plastic Injection Moulding &amp; Mould Development | Shakthi Enterprises</title>',home,count=1)
home=re.sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="Plastic injection moulding in Bengaluru. Shakthi Enterprises connects component design, mould development, production, inspection and assembly across two units with six machines from 40 to 500 tonnes.">',home,count=1)
home=home.replace('src="/landing.js"','src="/landing.js?v=injection-1"')
if '/injection-home.css' not in home:home=home.replace('</head>','<link rel="stylesheet" href="/injection-home.css?v=1"></head>')
home=home.replace('<span class="brand-symbol" aria-hidden="true">ϟ</span>','<img class="manufacturing-logo" src="/assets/logo.webp" alt="" width="60" height="40">').replace('<span class="brand-symbol">ϟ</span>','<img class="manufacturing-logo" src="/assets/logo.webp" alt="" width="60" height="40">')
home=re.sub(r'<div class="hero-title">.*?</div>','<div class="hero-title"><h1><span>PLASTIC</span><span>INJECTION</span><span>MOULDING.</span></h1></div>',home,count=1,flags=re.S)
home=re.sub(r'<div class="hero-introduction">.*?</div>','<div class="hero-introduction"><p><strong>SHAKTHI ENTERPRISES</strong><br>Plastic components, made to your requirement.<br>Tool design. Mould development.<br>Injection moulding. Assembly.</p></div>',home,count=1,flags=re.S)
home=home.replace('01 / THE TUBULAR BATTERY STUDY','01 / THE INJECTION MOULD ASSEMBLY').replace('Designed to make a difference.','From polymer to finished component.')
